// Tests the browser's viewer-key derivation against Node's WebCrypto.
//
// The property that matters most is agreement with the publisher: the same
// phrase and salt must produce the same 32 bytes in Rust and in the browser, or
// a viewer simply cannot decrypt anything. `viewer-key-vectors.json` is
// generated by the Rust side and pins that agreement here.

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const viewerKey = require('../crates/relay/static/viewer-key.js');

let failures = 0;
async function test(name, body) {
  try {
    await body();
    console.log(`  ok  ${name}`);
  } catch (error) {
    failures += 1;
    console.error(`  FAIL ${name}: ${error.message}`);
  }
}

await test('the wordlist is exactly ten bits wide', () => {
  assert.equal(viewerKey.WORDLIST.length, 1024);
  assert.equal(new Set(viewerKey.WORDLIST).size, 1024);
});

await test('no two words share a three-letter prefix', () => {
  const prefixes = new Set(viewerKey.WORDLIST.map(word => word.slice(0, 3)));
  assert.equal(prefixes.size, viewerKey.WORDLIST.length);
});

await test('the browser wordlist matches the publisher wordlist', () => {
  const canonical = readFileSync('crates/protocol/wordlist.txt', 'utf8').split('\n').filter(Boolean);
  assert.deepEqual(viewerKey.WORDLIST, canonical);
});

await test('spacing, case, and abbreviation all normalize the same way', () => {
  const words = viewerKey.WORDLIST.slice(0, 7);
  const canonical = words.join('-');
  assert.equal(viewerKey.normalizePhrase(canonical), canonical);
  assert.equal(viewerKey.normalizePhrase(words.join(' ')), canonical);
  assert.equal(viewerKey.normalizePhrase(canonical.toUpperCase()), canonical);
  assert.equal(viewerKey.normalizePhrase(words.map(w => w.slice(0, 3)).join(' ')), canonical);
});

await test('a wrong word count is rejected rather than padded', () => {
  assert.throws(() => viewerKey.normalizePhrase('able about acid'), /7 words/);
});

await test('an unknown word is rejected rather than ignored', () => {
  const phrase = ['zzzz', ...viewerKey.WORDLIST.slice(0, 6)].join('-');
  assert.throws(() => viewerKey.normalizePhrase(phrase), /not a GlacialCast/);
});

await test('the salt separates publishers', async () => {
  const phrase = viewerKey.WORDLIST.slice(0, 7).join('-');
  const first = await viewerKey.deriveFromPhrase(phrase, new Uint8Array(16).fill(1));
  const second = await viewerKey.deriveFromPhrase(phrase, new Uint8Array(16).fill(2));
  assert.equal(first.length, 32);
  assert.notDeepEqual([...first], [...second]);
});

await test('a raw base64 viewer key still resolves without a salt', async () => {
  const raw = viewerKey.bytesToBase64Url(new Uint8Array(32).fill(7));
  const bytes = await viewerKey.resolveKey(raw, null);
  assert.deepEqual([...bytes], Array.from({ length: 32 }, () => 7));
});

await test('a phrase without a salt is refused rather than mis-derived', async () => {
  const phrase = viewerKey.WORDLIST.slice(0, 7).join('-');
  await assert.rejects(() => viewerKey.resolveKey(phrase, null), /does not accept a key phrase/);
});

await test('the browser derives the same key bytes as the publisher', async () => {
  const vectors = JSON.parse(readFileSync('test-vectors/viewer-key-vectors.json', 'utf8'));
  assert.ok(vectors.cases.length > 0, 'the vector file must hold at least one case');
  for (const item of vectors.cases) {
    const bytes = await viewerKey.deriveFromPhrase(
      item.phrase,
      viewerKey.decodeSalt(item.salt_b64),
    );
    assert.equal(
      viewerKey.bytesToBase64Url(bytes),
      item.viewer_key_b64,
      `phrase "${item.phrase}" derived a different key than the publisher`,
    );
  }
});

console.log(failures === 0 ? 'PASS viewer key: 9 tests' : `FAIL viewer key: ${failures}`);
process.exit(failures === 0 ? 0 : 1);
